<!--
  生成的视频页面 - Generated Videos
  
  接口数据结构说明：
  - 接口返回包含task和media_list两个主要部分
  - task包含任务信息：id, task_id, status, progress, model, input_params, created_at等
  - media_list包含媒体文件信息：id, file_url, media_metadata, is_favorited等
  - 视频地址：media_list[0].file_url
  - 提示词：task.input_params.prompt 或 media_list[0].media_metadata.prompt
  - 收藏状态：media_list[0].is_favorited
  - 只显示status为"completed"且media_list不为空的任务
-->

<template>
  <div class="generated-videos-page hidden-scrollbar">
    <!-- 页面标题 -->
    <div v-if="showTitle" class="page-header">
      <h1 class="page-title">{{ t('videosGenerated') }}</h1>
    </div>

    <!-- 错误状态 -->
    <div v-if="errorMessage" class="error-container">
      <div class="error-text">{{ errorMessage }}</div>
      <l-button class="retry-btn" @click="loadVideoList" :text="t('retry')" ></l-button>
    </div>

    <!-- 空数据状态 -->
    <div v-else-if="videoList.length === 0 && !isLoading" class="empty-container">
      <l-img src="/static/images/empty-video.png" w="80px" h="auto" fit="cover" />
      <p class="empty-text">{{ dataSource === 'favorites' ? t('favorites.videoEmpty') : t('history.videoEmpty') }}</p>
    </div>

    <!-- 视频网格容器 -->
    <div v-if="videoList.length" class="videos-grid-container">
      <div class="videos-grid">
        <!-- 视频卡片列表 -->
        <div 
          v-for="video in videoList" 
          :key="video.id"
          class="video-card"
          :class="{ 'video-card-failed': video.taskStatus === 'failed' }"
          @click="handleVideoClick(video, $event)"
        >
          
          <!-- 视频显示区域 -->
          <div class="video-area">
            <div class="video-gradient">
              <!-- 视频播放器 -->
              <l-video
                v-if="video.videoUrl && video.videoUrl.trim() !== ''"
                :src="video.videoUrl || ''" 
                w="100%"
                h="100%"
                :show-controls="true"
                :muted="false"
                :preload="'metadata'"
                fit="contain"
                radius="8px"
                @error="handleVideoError"
                @loadedmetadata="handleVideoLoaded"
                @canplay="(event) => handleVideoCanPlay(video.id, event)"
                @play="(event) => handleVideoPlay(video.id, event)"
                @pause="(event) => handleVideoPause(video.id, event)"
                @ended="(event) => handleVideoEnded(video.id, event)"
                class="video-player"
              />
              
              <!-- 失败任务的占位显示 -->
              <div 
                v-else
                class="video-placeholder failed-placeholder"
              >
                <div class="placeholder-content">
                  <l-img 
                    src="/static/images/empty-video.png" 
                    w="64px" 
                    h="64px" 
                    fit="contain"
                    class="placeholder-icon"
                  />
                  <span class="placeholder-text">
                    {{ video.taskStatus === 'failed' ? (t('videoGenerationFailed') || 'Video generation failed') : (t('videoLoadError') || 'Video failed to load') }}
                  </span>
                </div>
              </div>
              
              <!-- 播放图标 (只在视频成功加载后显示) -->
              <div 
                v-if="video.videoUrl && video.videoUrl.trim() !== '' && videoLoadedStates[video.id]"
                @click.stop="handlePlayIconClick(video, $event)"
                class="play-icon-overlay"
              >
                <!-- 播放状态时显示暂停图标 -->
                <l-img 
                  v-if="videoPlayingStates[video.id]"
                  src="/static/images/pause-icon.png" 
                  w="35px" 
                  h="35px" 
                  fit="contain"
                  class="play-icon"
                />
                <!-- 暂停状态时显示播放图标 -->
                <l-img 
                  v-else
                  src="/static/images/videos/play_icon.png" 
                  w="35px" 
                  h="35px" 
                  fit="contain"
                  class="play-icon"
                />
              </div>
            </div>
          </div>
          
          <!-- 视频描述信息 -->
          <div class="video-info">
            <p class="video-description">{{ video.description }}</p>
          </div>
          <div class="video-footer">
            <p class="video-date">{{ video.createdDate }}</p>
          </div>
        </div>
      </div>
    </div>

    <!-- 分页组件 -->
    <div v-if="!isLoading && !errorMessage && videoList.length > 0" class="pagination-container">
      <Pagination
        :current-page="currentPage"
        :page-size="pageSize"
        :total="totalCount"
        :page-sizes="[10, 20, 30, 40, 50]"
        :show-page-sizes="true"
        :show-jumper="true"
        @current-change="handleCurrentChange"
        @size-change="handleSizeChange"
      />
    </div>

    <!-- 视频详情弹框 -->
    <ImageDetailDialogUnified
      v-model="showVideoDetail"
      :image-data="selectedVideo"
      :mode="currentMode"
    />
  </div>
</template>

<script setup>
import { ref, onMounted, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import LVideo from '@/components/l-video.vue';
import Pagination from '@/components/pagination.vue';
import ImageDetailDialogUnified from '@/components/produce-media/media-detail-dialog.vue';
import { ApiGeneration } from '@/api/api-generation';
import { fullScreenLoading } from '@/utils/ui-feedback';
import LButton from '@/components/l-button.vue';
import { GenerationType } from '@/types/enums';

// Props
const props = defineProps({
  showTitle: {
    type: Boolean,
    default: true
  },
  dataSource: {
    type: String,
    default: 'history', // 'history' | 'favorites'
    validator: (value) => ['history', 'favorites'].includes(value)
  }
});

// 多语言支持
const { t } = useI18n();

// 响应式数据
const currentPage = ref(1);
const pageSize = ref(20); // 固定20条
const totalCount = ref(0);
const videoList = ref([]);
const showVideoDetail = ref(false);
const selectedVideo = ref(null);
const currentMode = ref(GenerationType.TEXT_TO_VIDEO);

// 状态管理
const isLoading = ref(false);
const errorMessage = ref('');
const videoLoadedStates = ref({});
const videoPlayingStates = ref({}); // 跟踪每个视频的播放状态

// 监听事件区域
const handleVideoClick = (video, event) => {
  // 检查点击的是否是播放图标或其子元素
  const clickedElement = event.target;
  const playIconOverlay = clickedElement.closest('.play-icon-overlay');
  
  // 如果点击的是播放图标区域，不打开详情
  if (playIconOverlay) {
    console.log('Clicked on play icon, ignoring card click');
    return;
  }
  
  console.log('Video card clicked:', video);
  console.log('Video generation type:', video.generationType);
  
  // 根据视频的生成类型设置对应的模式
  if (video.generationType === 'text_to_video') {
    currentMode.value = GenerationType.TEXT_TO_VIDEO;
  } else if (video.generationType === 'image_to_video') {
    currentMode.value = GenerationType.IMAGE_TO_VIDEO;
  } else {
    // 默认使用文生视频模式
    currentMode.value = GenerationType.TEXT_TO_VIDEO;
  }
  
  console.log('Setting dialog mode to:', currentMode.value);
  
  selectedVideo.value = video;
  showVideoDetail.value = true;
};

const handlePlayIconClick = (video, event) => {
  console.log('Play icon clicked:', video);
  // 阻止事件传播（包括捕获和冒泡阶段）
  event.stopPropagation();
  event.stopImmediatePropagation();
  event.preventDefault();
  
  // 找到对应的视频元素并播放
  const videoCard = event.target.closest('.video-card');
  const videoElement = videoCard?.querySelector('video');
  
  if (videoElement) {
    console.log('Found video element:', videoElement);
    if (videoElement.paused) {
      console.log('Playing video...');
      videoElement.play().then(() => {
        // 播放成功后更新状态
        videoPlayingStates.value[video.id] = true;
      }).catch(error => {
        console.error('视频播放失败:', error);
      });
    } else {
      console.log('Pausing video...');
      videoElement.pause();
      // 暂停后更新状态
      videoPlayingStates.value[video.id] = false;
    }
  } else {
    console.warn('Video element not found');
  }
};

const handleVideoError = (error) => {
  console.error('Video load error:', error);
  console.error('Error target:', error.target);
  if (error.target) {
    console.error('Failed video src:', error.target.src);
  }
};

const handleVideoLoaded = (event) => {
  console.log('Video metadata loaded:', event);
  // 视频元数据加载完成，可以在这里进行额外处理
};

const handleVideoCanPlay = (id, event) => {
  console.log(`Video can play: ${id}`);
  videoLoadedStates.value[id] = true;
};

const handleVideoPlay = (id, event) => {
  console.log(`Video play: ${id}`);
  videoPlayingStates.value[id] = true;
};

const handleVideoPause = (id, event) => {
  console.log(`Video pause: ${id}`);
  videoPlayingStates.value[id] = false;
};

const handleVideoEnded = (id, event) => {
  console.log(`Video ended: ${id}`);
  videoPlayingStates.value[id] = false;
};

const handleCurrentChange = (page) => {
  currentPage.value = page;
  loadVideoList();
};

const handleSizeChange = (size) => {
  pageSize.value = size;
  currentPage.value = 1;
  loadVideoList();
};

// 业务逻辑区域
const loadVideoList = async () => {
  const loading = fullScreenLoading();
  try {
    isLoading.value = true;  
    errorMessage.value = '';
    
    // 重置视频加载状态
    videoLoadedStates.value = {};
    
    // 重置视频播放状态
    videoPlayingStates.value = {};
    
    // 构建请求参数
    const params = {
      media_type: 'video',
      page: currentPage.value,
      page_size: pageSize.value
    };

    console.log('Loading video list with params:', params);
    console.log('Data source:', props.dataSource);

    // 根据数据源调用不同的API
    const response = props.dataSource === 'favorites' 
      ? await ApiGeneration.getFavorites(params)
      : await ApiGeneration.getHistory(params);

    console.log('API Response:', response);

    // 检查响应状态
    if (response.code !== 200) {
      throw new Error(response.message || 'Failed to load videos');
    }

    // 检查响应数据结构
    if (!response.data || !response.data.items) {
      console.warn('Invalid response data structure:', response.data);
      throw new Error('Invalid response data structure');
    }

    // 转换分页数据
    const paginationData = ApiGeneration.transformPaginationData(response);
    console.log('Pagination data:', paginationData);
    
    // 转换视频数据 - 传入原始items数组
    const transformedVideos = ApiGeneration.transformToVideoData(paginationData.items);
    console.log('Transformed videos:', transformedVideos);
    
    // 更新状态
    videoList.value = transformedVideos;
    totalCount.value = paginationData.total;
    currentPage.value = paginationData.currentPage;
    pageSize.value = paginationData.pageSize;

    console.log('Final state:', {
      videoCount: videoList.value.length,
      totalCount: totalCount.value,
      currentPage: currentPage.value,
      pageSize: pageSize.value
    });

    loading.close();
    isLoading.value = false;
    
  } catch (error) {
    console.error('Error loading video list:', error);
    errorMessage.value = props.dataSource === 'favorites' 
      ? t('favorites.error') 
      : t('history.error');
    
    // 设置空数据
    videoList.value = [];
    totalCount.value = 0;
  } finally {
    loading.close();
    isLoading.value = false;
  }
};

// 监听props变化
watch(() => props.dataSource, () => {
  // 数据源变化时重置分页并重新加载
  currentPage.value = 1;
  loadVideoList();
}, { immediate: false });

// 周期函数区域
onMounted(() => {
  loadVideoList();
});
</script>

